from __future__ import annotations


def compress_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    unique_sorted = sorted(set(nums))
    ranges: list[str] = []

    start = unique_sorted[0]
    end = start

    for n in unique_sorted[1:]:
        if n == end + 1:
            end = n
        else:
            ranges.append(_format_range(start, end))
            start = n
            end = n

    ranges.append(_format_range(start, end))
    return ",".join(ranges)


def _format_range(start: int, end: int) -> str:
    length = end - start + 1
    if length >= 3:
        return f"{start}-{end}"
    elif length == 2:
        return f"{start},{end}"
    else:
        return str(start)
